import * as React from "react";
import { Link as I18nLink } from "gatsby-plugin-react-i18next";

type AppLinkProps = {
  to: string;
  children: React.ReactNode;
  className?: string;
  activeClassName?: string;
  partiallyActive?: boolean;
  language?: string;
  onClick?: React.MouseEventHandler<HTMLAnchorElement>;
  "aria-label"?: string;
};

const AppLink = React.forwardRef<HTMLAnchorElement, AppLinkProps>(
  ({ children, ...props }, ref) => {
    // Cast controlado: evita que TS te exija props absurdos y evita pasar handlers inválidos al DOM
    return (
      <I18nLink ref={ref as any} {...(props as any)}>
        {children}
      </I18nLink>
    );
  }
);

AppLink.displayName = "AppLink";
export default AppLink;
